    sdwa_src1_neg_ = sw->src1_neg;
    sdwa_src1_abs_ = sw->src1_abs;
    sdwa_sdst_ = sw->sdst;
    sdwa_sd_ = sw->sd;
    if (sw->s1)
      vsrc1 = Operand(32, OperandType::OPR_SRC, reinterpret_cast<const OpEncoding *>(inst)->vsrc1);
